void batched_gemm_fp16(const half* __restrict__ A,
                       const half* __restrict__ B,
                       half* __restrict__ C,
                       const int batch,
                       const int M,
                       const int K,
                       const int N) {
    const int TILE_M = 32;
    const int TILE_N = 32;
    const int TILE_K = 32;

    __shared__ half As[TILE_M][TILE_K];
    __shared__ half Bs[TILE_K][TILE_N];

    const int batch_idx = blockIdx.z;
    const int row = blockIdx.y * TILE_M + threadIdx.y;   // M dimension
    const int col = blockIdx.x * TILE_N + threadIdx.x;   // N dimension

    float acc = 0.0f;

    for (int t = 0; t < K; t += TILE_K) {
        // ---- load A tile -------------------------------------------------
        const int a_row = row;
        const int a_col = t + threadIdx.x;
        if (a_row < M && a_col < K) {
            As[threadIdx.y][threadIdx.x] =
                A[batch_idx * M * K + a_row * K + a_col];
        } else {
            As[threadIdx.y][threadIdx.x] = __float2half(0.0f);
        }

        // ---- load B tile -------------------------------------------------
        const int b_row = t + threadIdx.y;
        const int b_col = col;
        if (b_row < K && b_col < N) {
            Bs[threadIdx.y][threadIdx.x] =
                B[batch_idx * K * N + b_row * N + b_col];
        } else {
            Bs[threadIdx.y][threadIdx.x] = __float2half(0.0f);
        }

        __syncthreads();

        // ---- compute partial product --------------------------------------
        #pragma unroll
        for (int k = 0; k < TILE_K; ++k) {
            acc += __half2float(As[threadIdx.y][k]) *
                   __half2float(Bs[k][threadIdx.x]);
        }

        __syncthreads();
    }

    // ---- write result ----------------------------------------------------
    if (row < M && col < N) {
        C[batch_idx * M * N + row * N + col] = __float2half(acc);
    }
}
'''

